#!/usr/bin/env bash
# gen-static-baseline.sh — generate the STATIC arm's hand-written-style AGENTS.md.
#
# The STATIC arm is the realistic control: a project's normal static AGENTS.md
# (project overview + build/test/lint commands + conventions) with NO pmd blocks.
# It must be generated by a model so the comparison is "real agent context file
# vs pipemd-injected context file", not "human-authored vs machine".
#
# Generated ONCE per target with a (cheaper) model, cached on disk, committed.
# The bench harness copies the cached file into each STATIC worktree.
#
# Usage: bash bench/gen-static-baseline.sh <target> [model]
#   target = hono | bt-lua | python | go
#   model  = opencode model id (default zai-coding-plan/glm-5.1)
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
TARGET="${1:-}"
MODEL="${2:-zai-coding-plan/glm-5.1}"

if [ -z "$TARGET" ]; then
  echo "Usage: $0 <target> [model]  (target: hono|bt-lua|python|go)"
  exit 1
fi

REPO_DIR="$SCRIPT_DIR/repos/${TARGET}-clean"
OUT_DIR="$SCRIPT_DIR/baselines/static-agents"
OUT="$OUT_DIR/${TARGET}.AGENTS.md"

if [ ! -d "$REPO_DIR" ]; then
  echo "Error: $REPO_DIR not found" >&2; exit 1
fi

mkdir -p "$OUT_DIR"
if [ -f "$OUT" ]; then
  echo "Cached: $OUT ($(wc -l < "$OUT") lines) — delete to regenerate"
  exit 0
fi

PROMPT_FILE="$SCRIPT_DIR/prompts/_gen-agents.md"
[ -f "$PROMPT_FILE" ] || { echo "Error: $PROMPT_FILE not found" >&2; exit 1; }
PROMPT="$(cat "$PROMPT_FILE")"

# Render in a throwaway copy so the source repo stays pristine.
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT
cp -r "$REPO_DIR/." "$WORK/"
rm -rf "$WORK/.git" "$WORK/node_modules" "$WORK/.venv" 2>/dev/null || true

# Auto-approve writes so the model can create AGENTS.md without prompting.
cat > "$WORK/opencode.json" << 'PERM_EOF'
{
  "$schema": "https://opencode.ai/config.json",
  "permission": {
    "read": "allow", "edit": "allow", "write": "allow",
    "bash": "allow", "glob": "allow", "grep": "allow", "list": "allow", "task": "allow"
  }
}
PERM_EOF

echo "Generating $TARGET static baseline with $MODEL..."
# opencode writes the AGENTS.md into the work dir.
timeout 300 opencode run --format json --model "$MODEL" --dir "$WORK" "$PROMPT" \
  > "$WORK/gen.ndjson" 2>"$WORK/gen.err" || true

if [ ! -f "$WORK/AGENTS.md" ]; then
  echo "Error: model did not produce AGENTS.md in $WORK" >&2
  echo "--- last tool/text events ---" >&2
  jq -r 'select(.type=="tool_use" or .type=="text") | if .type=="text" then "TEXT: " + (.part.text//"") else "TOOL: " + (.part.tool//"") + " status=" + (.part.state.status//"") end' "$WORK/gen.ndjson" 2>/dev/null | tail -15 >&2
  cat "$WORK/gen.err" 2>/dev/null | tail -5 >&2
  exit 1
fi

# Hygiene: strip any accidental pmd markers (the static arm MUST have none),
# and cap absurd length.
sed -i '/<!-- pmd:/,/<!-- \/pmd -->/d' "$WORK/AGENTS.md" 2>/dev/null || true
cp "$WORK/AGENTS.md" "$OUT"

LINES=$(wc -l < "$OUT")
BLOCKS=$(grep -c 'pmd:' "$OUT" || true)
echo "Wrote $OUT ($LINES lines, $BLOCKS pmd blocks [must be 0])"
[ "$BLOCKS" -eq 0 ] || { echo "ERROR: static baseline contains pmd blocks" >&2; exit 1; }
